import {jailCapacity,jailStatus} from './jail.js?v=architecture-collection-36';
import {SERVICES,civicRoots,isCivicRoot,civicMembers,civicRoadIds,civicCenter,civicServiceOperating} from './civic-footprints.js?v=architecture-collection-36';
import {hospitalStaffing,hospitalizationRate} from './hospital.js?v=architecture-collection-36';
import {activeCityHalls,cityHallCrimeRelief,activeCourthouses,courthouseCrimeRelief} from './rewards.js?v=architecture-collection-36';
import {auraBreakdown} from './aura.js?v=architecture-collection-36';
import {advanceEducation,initialAgeEducation,educationWeights,educationServiceDemand,refreshEducationAverages} from './education.js?v=architecture-collection-36';
import {healthOutlook} from './health.js?v=architecture-collection-36';
import {casinoCrime,businessRoots} from './business.js?v=architecture-collection-36';
import {occupancy} from './utilities.js?v=architecture-collection-36';
// Manual pp.106–113 describes relationships; radii, capacities and rates below are calibration approximations.
export {SERVICES,civicServiceOperating} from './civic-footprints.js?v=architecture-collection-36';

export function serviceRadius(c,t){const d=SERVICES[t.type],funding=d?c.civic.funding[d.department]:0,effective=Math.min(110,funding)+Math.max(0,funding-110)*.1;return t.serviceActive&&d?.radius?d.radius*Math.sqrt(effective/100):0;}
export const DEPARTMENTS={police:'Police',fire:'Fire',health:'Healthcare',education:'Education'};
import {ORDINANCES} from './ordinances.js?v=architecture-collection-36';
export {ORDINANCES} from './ordinances.js?v=architecture-collection-36';
const clamp=(v,a=0,b=100)=>Math.max(a,Math.min(b,v));
// Manual p.106 links good fire coverage with land value; eight points is reconstruction tuning.
export function applyFireLandValue(t){const before=t.landValue;t.landValue=clamp(before+(t.terrain!=='water'&&!t.radiation?t.fireCoverage*.08:0),1,100);t.fireLandBonus=t.landValue-before;}

export const freshCivic=()=>({funding:Object.fromEntries(Object.keys(DEPARTMENTS).map(k=>[k,100])),underfunded:Object.fromEntries(Object.keys(DEPARTMENTS).map(k=>[k,0])),ageEducation:initialAgeEducation(),education:40,youthEducation:40,adultEducation:40,lifeExpectancy:59,ordinances:Object.fromEntries(Object.keys(ORDINANCES).map(k=>[k,false]))});
export function changeCivic(c,funding,ordinances){if(!funding||Object.keys(DEPARTMENTS).some(k=>!Number.isInteger(funding[k])||funding[k]<0||funding[k]>150)||!ordinances||Object.keys(ORDINANCES).some(k=>typeof ordinances[k]!=='boolean'))return{ok:false,error:'Service funding must be 0–150%; choose valid ordinance settings.'};c.civic.funding=Object.fromEntries(Object.keys(DEPARTMENTS).map(k=>[k,funding[k]]));c.civic.ordinances=Object.fromEntries(Object.keys(ORDINANCES).map(k=>[k,ordinances[k]]));return{ok:true};}
export const ordinanceCost=(c,key)=>Math.ceil((ORDINANCES[key]?.cost||0)+(ORDINANCES[key]?.perResident||0)*(c.stats.population||0));
export function civicSpending(c,funding=c.civic.funding,ordinances=c.civic.ordinances){const result=Object.fromEntries(Object.keys(DEPARTMENTS).map(k=>[k,0]));for(const t of civicRoots(c)){const s=SERVICES[t.type];if(s)result[s.department]+=s.upkeep*funding[s.department]/100;}for(const k of Object.keys(result))result[k]=Math.round(result[k]);result.ordinances=Object.entries(ORDINANCES).reduce((v,[k,o])=>v+(ordinances[k]?ordinanceCost(c,k):0),0);return result;}
export function recomputeCivic(c){
 const halls=activeCityHalls(c),courts=activeCourthouses(c),casinos=businessRoots(c),state=c.civic,tiles=c.tiles,n=Math.sqrt(tiles.length),homes=tiles.filter(t=>t.type==='residential'&&t.level),population=homes.reduce((v,t)=>v+occupancy(t.level)*8,0),counts={},active={},capacities={};
 const patientRate=hospitalizationRate(c),educationMix=educationWeights(c,population);refreshEducationAverages(c,population);
 for(const k of Object.keys(SERVICES)){counts[k]=0;active[k]=0;capacities[k]=0;}
 const strikes=Object.keys(DEPARTMENTS).filter(k=>state.underfunded[k]>=6);
 for(const t of tiles){t.aura=0;t.policeCoverage=0;t.policePresence=0;t.fireCoverage=0;t.fireProtection=0;t.healthCoverage=0;t.educationCoverage=0;t.schoolCoverage=0;t.childEducationCoverage=0;t.collegeEducationCoverage=0;t.adultEducationCoverage=0;t.libraryEducationCoverage=0;t.museumEducationCoverage=0;t.serviceActive=false;t.crime=0;t.flammability=t.type?(t.type==='industrial'?80:60)*(t.watered?.35:1)*(state.ordinances.fireCode?.8:1):0;const s=SERVICES[t.type];if(!s||!isCivicRoot(t))continue;counts[t.type]++;t.serviceActive=civicServiceOperating(c,t);if(t.serviceActive){active[t.type]++;capacities[t.type]+=t.type==='hospital'?hospitalStaffing(state.funding.health).capacity:t.type==='jail'?jailCapacity(state.funding.police).capacity:(s.capacity||0)*state.funding[s.department]/100;}}
 for(const root of civicRoots(c))for(const member of civicMembers(c,root))member.serviceActive=root.serviceActive;
 const jailNeed=Math.ceil(population*.01),jails=jailStatus(jailNeed,capacities.jail,active.jail*jailCapacity(state.funding.police).maximum),jailAdequacy=jailNeed?Math.min(1,capacities.jail/jailNeed):1;
 for(const t of civicRoots(c)){const s=SERVICES[t.type];if(!s||!t.serviceActive||!s.radius)continue;const center=civicCenter(t),funding=state.funding[s.department]/100,r=serviceRadius(c,t),field=t.type==='police'?'policeCoverage':'fireCoverage';for(let y=Math.max(0,Math.floor(center.y-r));y<=Math.min(n-1,Math.ceil(center.y+r));y++)for(let x=Math.max(0,Math.floor(center.x-r));x<=Math.min(n-1,Math.ceil(center.x+r));x++){const d=Math.hypot(x-center.x,y-center.y);if(d<=r)tiles[y*n+x][field]+=100*funding*(t.type==='fire'?1:1-.75*d/r)*(t.type==='police'?jails.policeEffectiveness:1);}}
 // Capacity is shared among homes reached on the same road component, not credited to disconnected neighborhoods.
 for(const t of civicRoots(c)){const s=SERVICES[t.type];if(!s||!t.serviceActive||!['hospital','school','college','library','museum'].includes(t.type))continue;const ids=civicRoadIds(c,t),served=homes.filter(h=>h.roadIds.some(id=>ids.includes(id))),people=served.reduce((v,h)=>v+occupancy(h.level)*8,0);if(!people)continue;const demand=t.type==='hospital'?{share:patientRate,field:'healthCoverage'}:educationServiceDemand(c,t.type,population);if(!demand.share)continue;const available=t.type==='hospital'?hospitalStaffing(state.funding.health).capacity:s.capacity*state.funding[s.department]/100,coverage=100*available/(people*demand.share);for(const h of served){h[demand.field]+=coverage;if(t.type==='library')h.libraryEducationCoverage+=coverage;if(t.type==='museum')h.museumEducationCoverage+=coverage;}}
 // Restore environmental values so repeated civic recomputation cannot compound penalties.
 for(const t of tiles){t.landValue=t.environmentLandValue??t.landValue;t.crimeLandPenalty=0;t.fireLandBonus=0;t.cityHallCrimeRelief=0;t.courthouseCrimeRelief=0;}
 for(const jail of civicRoots(c).filter(t=>t.type==='jail'))for(const h of homes)if(Math.hypot(jail.x-h.x,jail.y-h.y)<5)h.landValue=clamp(h.landValue-8,1,100);
 let crime=0,fire=0,police=0,health=0,education=0,school=0,child=0,college=0,adult=0,library=0,museum=0,aura=0;
 for(const t of tiles){t.aura=0;t.policePresence=Math.max(0,t.policeCoverage);t.policeCoverage=clamp(t.policeCoverage);t.fireProtection=Math.max(0,t.fireCoverage);t.fireCoverage=clamp(t.fireCoverage);t.healthCoverage=clamp(t.healthCoverage);t.childEducationCoverage=clamp(t.childEducationCoverage);t.collegeEducationCoverage=clamp(t.collegeEducationCoverage);t.schoolCoverage=educationMix.youth?(t.childEducationCoverage*educationMix.counts[0]+t.collegeEducationCoverage*educationMix.counts[1])/(population*educationMix.youth):0;t.adultEducationCoverage=clamp(t.adultEducationCoverage);t.libraryEducationCoverage=clamp(t.libraryEducationCoverage);t.museumEducationCoverage=clamp(t.museumEducationCoverage);t.educationCoverage=t.schoolCoverage*educationMix.youth+t.adultEducationCoverage*educationMix.adult;if(!t.type){applyFireLandValue(t);continue;}
 t.crime=clamp((35+casinoCrime(casinos,t)+(t.universityCrimePressure||0)+(t.stadiumCrimePressure||0)+(t.themeParkCrimePressure||0)+(t.stockExchangeCrimePressure||0)+occupancy(t.level)*2+(100-t.landValue)*.12-state.education*.2)*(1-t.policeCoverage/125)*(state.ordinances.watch?.85:1)*(state.ordinances.juniorSports?.95:1));
 const rawCrime=t.crime;t.crime=Math.max(0,t.crime-cityHallCrimeRelief(halls,t));t.cityHallCrimeRelief=rawCrime-t.crime;const beforeCourt=t.crime;t.crime=Math.max(0,t.crime-courthouseCrimeRelief(courts,t));t.courthouseCrimeRelief=beforeCourt-t.crime;
 const beforeCrime=t.landValue;t.landValue=clamp(t.landValue-t.crime*.2,1,100);t.crimeLandPenalty=beforeCrime-t.landValue;applyFireLandValue(t);
 if(t.type==='residential'&&t.level){const w=occupancy(t.level)*8;crime+=t.crime*w;police+=t.policeCoverage*w;fire+=t.fireCoverage*w;health+=t.healthCoverage*w;education+=t.educationCoverage*w;school+=t.schoolCoverage*w;child+=t.childEducationCoverage*w;college+=t.collegeEducationCoverage*w;adult+=t.adultEducationCoverage*w;library+=t.libraryEducationCoverage*w;museum+=t.museumEducationCoverage*w;aura+=(t.aura=auraBreakdown(c,t).value)*w;}
 }
 const avg=v=>population?v/population:0;
 const zones=tiles.filter(t=>['residential','commercial','industrial'].includes(t.type));
 return{recreationHealth:population?homes.reduce((v,t)=>v+(t.recreationHealth||0)*occupancy(t.level)*8,0)/population:0,averageLandValue:zones.length?zones.reduce((v,t)=>v+t.landValue,0)/zones.length:0,serviceCounts:counts,activeServices:active,serviceCapacities:capacities,strikes,jailNeed,jailAdequacy,jails,averageCrime:avg(crime),policeCoverage:avg(police),fireCoverage:avg(fire),healthCoverage:avg(health),educationCoverage:avg(education),schoolCoverage:avg(school),childEducationCoverage:avg(child),collegeEducationCoverage:avg(college),adultEducationCoverage:avg(adult),libraryEducationCoverage:avg(library),museumEducationCoverage:avg(museum),youthEducation:state.youthEducation,adultEducation:state.adultEducation,education:state.education,lifeExpectancy:state.lifeExpectancy,aura:avg(aura)};
}
export function advanceCivic(c){const s=c.stats,f=c.civic;for(const k of Object.keys(DEPARTMENTS)){const hasBuilding=c.tiles.some(t=>SERVICES[t.type]?.department===k);f.underfunded[k]=hasBuilding&&f.funding[k]<50?Math.min(120000,f.underfunded[k]+1):f.funding[k]>=100||!hasBuilding?0:f.underfunded[k];}if(!s.population)return;advanceEducation(c);const healthTarget=healthOutlook(c).target;f.lifeExpectancy=clamp(f.lifeExpectancy+(healthTarget-f.lifeExpectancy)/48,45,90);}
export function validateCivic(v){const result=freshCivic(),holder={civic:result};if(!v||!Array.isArray(v.ageEducation)||v.ageEducation.length!==8||v.ageEducation.some(eq=>!Number.isFinite(eq)||eq<0||eq>100)||['youthEducation','adultEducation'].some(k=>!Number.isFinite(v[k])||v[k]<0||v[k]>100)||!changeCivic(holder,v.funding,v.ordinances).ok||!v.underfunded||Object.keys(DEPARTMENTS).some(k=>!Number.isInteger(v.underfunded[k])||v.underfunded[k]<0||v.underfunded[k]>120000)||!Number.isFinite(v.education)||v.education<0||v.education>100||!Number.isFinite(v.lifeExpectancy)||v.lifeExpectancy<45||v.lifeExpectancy>90)throw Error('Invalid civic service data.');result.underfunded=Object.fromEntries(Object.keys(DEPARTMENTS).map(k=>[k,v.underfunded[k]]));result.ageEducation=[...v.ageEducation];result.education=v.education;result.youthEducation=v.youthEducation;result.adultEducation=v.adultEducation;result.lifeExpectancy=v.lifeExpectancy;return result;}

export function ordinanceRevenue(c,ordinances=c.civic.ordinances){
 const s=c.stats,drivers=Math.max(0,(s.commuters||0)-(s.unemployed||0)-(s.busRiders||0)-(s.trainRiders||0))*(ordinances.carpool?.7:1);
 return{parkingFines:ordinances.parkingFines?Math.floor(drivers*.5):0};
}
